              "applicability": {
                "mode": "script",
                "value": "(function execute() {\n    if(vaVars.location_mobile_cred_enabled){\n        if(vaVars.location_mobile_cred_enabled == \"false\"){\n           return false;\n        }\n        var badgeTypeData = vaVars.badge_type;\n        var badgeTypeInputData = vaInputs.badge_type;  \n        if(badgeTypeData == \"\" && badgeTypeInputData == \"\"){\n             return true;\n        }\n        if(badgeTypeData.indexOf(\"perm\") > -1 ||  badgeTypeData.indexOf(\"temp\") > -1 ){\n            return true;\n        }\n     }\n     return false;\n\n})()\n"
